contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint amount, string memory typeStr, address proposedAddress) public payable {
        require(amount < 2**250);
        uint before = c.proposalCount();
        // separate address proposal to advance the counter independently
        c.newAddressProposal(proposedAddress, typeStr);
        uint afterAddr = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint afterGrant = c.proposalCount();
        (address storedRecipient, uint storedAmount) = c.mapPID_grant(afterGrant);
        assert(
            afterAddr == before + 1 &&
            afterGrant == before + 2 &&
            storedRecipient == recipient &&
            storedAmount == amount &&
            c.mapPID_votes(afterGrant) == 0 &&
            c.mapPID_finalised(afterGrant) == false &&
            c.mapPID_finalising(afterGrant) == false &&
            keccak256(bytes(c.mapPID_type(afterGrant))) == keccak256(bytes("GRANT"))
        );
    }
    receive() external payable {}
}

