        require(recipient != address(0));
        c.init(address(this), address(this), address(this));
        c.newGrantProposal(recipient, amount);
        uint pid = c.proposalCount();
        uint returnedWeight = c.voteProposal(pid);
        uint recordedVotes = c.mapPID_votes(pid);
        uint memberVotes = c.mapPIDMember_votes(pid, address(this));
        assert(returnedWeight == MEMBER && recordedVotes == MEMBER && memberVotes == MEMBER);
    }

    fallback(bytes calldata data) external payable returns (bytes memory) {
        bytes4 sel = bytes4(data[:4]);
        if (sel == bytes4(keccak256("getMemberWeight(address)"))) {
            return abi.encode(MEMBER);
        }
        // totalWeight() and any other view
        return abi.encode(TOTAL);
    }

    receive() external payable {}
}

