contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address recipient) public {
        require(recipient != address(0));
        c.init(address(this), address(this), address(this));
        c.newGrantProposal(recipient, 1);
        uint pid = c.proposalCount();
        // vote; VAULT is this contract, whose fallback returns a huge weight,
        // so the single vote exceeds totalWeight/3 (quorum) and triggers _finalise
        c.voteProposal(pid);
        require(c.mapPID_finalising(pid));
        bool reverted;
        try c.finaliseProposal(pid) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        // serves VAULT.totalWeight() and VAULT.getMemberWeight(): return a large weight
        return abi.encode(type(uint256).max / 4);
    }

    receive() external payable {}
}

