        uint before = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint pid = c.proposalCount();
        bool okCount = (pid == before + 1);
        (string memory t1, , ) = c.mapPID_grant(pid);
        bool okType = keccak256(bytes(c.mapPID_type(pid))) == keccak256(bytes("GRANT"));
        // second proposal: an address proposal must not disturb the grant record
        c.newAddressProposal(proposedAddress, typeStr);
        uint pid2 = c.proposalCount();
        (address r1, uint a1) = c.mapPID_grant(pid);
        assert(okCount && okType && pid2 == pid + 1 && r1 == recipient && a1 == amount);
    }
