        c.newGrantProposal(recipient, amount);
        uint pid = c.proposalCount();
        (address r1, uint a1) = c.mapPID_grant(pid);
        c.newAddressProposal(proposedAddress, typeStr);
        uint pid2 = c.proposalCount();
        (address r2, uint a2) = c.mapPID_grant(pid);
        assert(
            pid == before + 1 &&
            keccak256(bytes(c.mapPID_type(pid))) == keccak256(bytes("GRANT")) &&
            r1 == recipient && a1 == amount &&
            pid2 == pid + 1 &&
            r2 == r1 && a2 == a1
